class GlyphEngine final : public QIconEngine {
public:
    explicit GlyphEngine(const QString& glyph) : m_glyph(glyph) {}
    QIconEngine* clone() const override { return new GlyphEngine(m_glyph); }
    QPixmap pixmap(const QSize& size, QIcon::Mode mode, QIcon::State) override {
        QPixmap pm(size);
        pm.fill(Qt::transparent);
        fluent::FontIcon renderer(m_glyph);
        renderer.setIconSize(qMin(size.width(), size.height()));
        renderer.setEnabled(mode != QIcon::Disabled);
        renderer.resize(size);
        QPainter painter(&pm);
        renderer.render(&painter, QPoint(), QRegion(), QWidget::DrawChildren);
        return pm;
    }
    void paint(QPainter* painter, const QRect& rect, QIcon::Mode mode, QIcon::State state) override {
        const int dpr = painter->device() ? qMax(1, qRound(painter->device()->devicePixelRatioF())) : 1;
        painter->drawPixmap(rect, pixmap(rect.size() * dpr, mode, state));
    }
private:
    QString m_glyph;
};
auto* rootLayout = new QVBoxLayout(%PARENT%);
rootLayout->setContentsMargins(0, 0, 0, 0);
auto* card = new fluent::layout::Card(%PARENT%);
card->setAppearance(fluent::layout::Card::LayerAlt);
rootLayout->addWidget(card);
auto* cardLayout = new QVBoxLayout(card);
cardLayout->setContentsMargins(12, 10, 12, 12);
cardLayout->setSpacing(8);
auto* control = new fluent::navigation::SelectorBar(card);
auto* pageHost = new fluent::navigation::StackContentHost(card);
pageHost->setTransitionAnimationEnabled(false);
struct SelectorPageSpec {
    QString title;
    QString glyph;
    QString summary;
};
const QVector<SelectorPageSpec> specs{
    {QStringLiteral("Inbox"), Typography::Icons::Mail, QStringLiteral("Unread messages, mentions, and prioritized threads.")},
    {QStringLiteral("Calendar"), Typography::Icons::Calendar, QStringLiteral("Upcoming design reviews and release syncs.")},
    {QStringLiteral("Tasks"), Typography::Icons::List, QStringLiteral("Open action items assigned to this milestone.")},
    {QStringLiteral("Contacts"), Typography::Icons::Contact, QStringLiteral("Contributors and external collaborators.")},
    {QStringLiteral("Documents"), Typography::Icons::Document, QStringLiteral("Shared specifications, specs, and notes.")},
    {QStringLiteral("Flagged"), Typography::Icons::Flag, QStringLiteral("Starred discussions requiring follow-up.")},
    {QStringLiteral("Settings"), Typography::Icons::Settings, QStringLiteral("Sync interval and section visibility rules.")},
};
for (int i = 0; i < specs.size(); ++i) {
    control->addItem(fluent::navigation::SelectorBarItem(specs.at(i).title, specs.at(i).glyph));
    auto* page = new fluent::layout::Card(pageHost);
    auto* pageLayout = new QVBoxLayout(page);
    pageLayout->setContentsMargins(14, 12, 14, 12);
    pageLayout->setSpacing(4);
    auto* heading = new fluent::textfields::Label(specs.at(i).title, page);
    heading->setFluentTypography(Typography::FontRole::BodyStrong);
    auto* body = new fluent::textfields::Label(specs.at(i).summary, page);
    body->setFluentTypography(Typography::FontRole::Caption);
    body->setTextColorRole(fluent::textfields::Label::TextColorRole::Secondary);
    body->setWordWrap(true);
    pageLayout->addWidget(heading);
    pageLayout->addWidget(body);
    pageLayout->addStretch(1);
    pageHost->insertPage(i, page);
}
control->setSelectedIndex(0);
pageHost->setCurrentIndex(0, 0, false);
auto* overflowMenu = new fluent::menus_toolbars::FluentMenu(QStringLiteral("Overflow"), control);
QObject::connect(control, &fluent::navigation::SelectorBar::currentChanged, pageHost, [pageHost](int index) {
    if (index >= 0 && index < pageHost->count())
        pageHost->setCurrentIndex(index, 0, false);
});
QObject::connect(control, &fluent::navigation::SelectorBar::overflowActivated, control, [control, overflowMenu](const QVector<int>& hiddenIndexes) {
    if (hiddenIndexes.isEmpty())
        return;
    overflowMenu->clear();
    for (int index : hiddenIndexes) {
        const auto item = control->itemAt(index);
        auto* action = overflowMenu->addAction(item.text);
        if (!item.iconGlyph.isEmpty())
            action->setIcon(QIcon(new GlyphEngine(item.iconGlyph)));
        QObject::connect(action, &QAction::triggered, control, [control, index] {
            control->setSelectedIndex(index);
        });
    }
    const QRect anchor = control->overflowGeometry();
    overflowMenu->popup(control->mapToGlobal(anchor.isValid() ? anchor.bottomLeft() : QPoint(0, control->height())));
});
cardLayout->addWidget(control);
cardLayout->addWidget(pageHost, 1);
